 public static T Begin<T>(string folder) where T:SportsEventSession {foreach(var f in new[]{"Scenes","Materials","Audio"})Directory.CreateDirectory("Assets/"+folder+"/"+f);AssetDatabase.Refresh();EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject(folder+" Authority");var m=root.AddComponent<T>();m.settings=root.AddComponent<SportsSettings>();m.feedback=root.AddComponent<SportsFeedback>();m.feedback.settings=m.settings;m.feedback.voices=8;root.AddComponent<AudioListener>();SportsUIAuthoring.Events(root);var sun=new GameObject("Sports sunlight").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(48,-28,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.53f,.62f,.7f);RenderSettings.fog=false;var sky=Mat(folder,"Arena sky",new Color(.4f,.65f,.85f));sky.shader=Shader.Find("Skybox/Procedural");sky.SetColor("_SkyTint",new Color(.45f,.62f,.8f));sky.SetFloat("_AtmosphereThickness",.85f);RenderSettings.skybox=sky;return m;}
 public static Material Mat(string folder,string name,Color color,float smooth=.3f){string path="Assets/"+folder+"/Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",smooth);m.enableInstancing=true;return m;}
 public static PhysicsMaterial Contact(string folder,string name,float friction,float bounce){string path="Assets/"+folder+"/Materials/"+name+".asset";var m=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(m==null){m=new PhysicsMaterial(name);AssetDatabase.CreateAsset(m,path);}m.dynamicFriction=m.staticFriction=friction;m.bounciness=bounce;m.frictionCombine=PhysicsMaterialCombine.Minimum;m.bounceCombine=PhysicsMaterialCombine.Average;return m;}
 public static GameObject Box(string name,Vector3 p,Vector3 scale,Material mat,PhysicsMaterial physics=null,Transform parent=null){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;if(physics==null)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());else g.GetComponent<Collider>().sharedMaterial=physics;return g;}
 public static TextMesh Label(string name,string text,Vector3 p,float size,Color color){var g=new GameObject(name);g.transform.position=p;var t=g.AddComponent<TextMesh>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.fontSize=64;t.characterSize=size;t.text=text;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=color;g.GetComponent<Renderer>().sharedMaterial=t.font.material;return t;}
 public static SportsEventTruck Truck(SportsEventSession m,string folder,string name,Vector3 position,int slot,float length=3){var g=new GameObject(name);g.layer=2;g.transform.position=position;var b=g.AddComponent<Rigidbody>();b.mass=12;b.useGravity=true;b.interpolation=RigidbodyInterpolation.Interpolate;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;b.solverIterations=12;b.maxDepenetrationVelocity=3;b.angularDamping=.45f;b.centerOfMass=new Vector3(0,.03f,0);var box=g.AddComponent<BoxCollider>();box.size=new Vector3(1.2f,.65f,2.7f);box.center=new Vector3(0,.2f,0);box.sharedMaterial=Contact(folder,"Truck physical contact",.15f,.12f);var t=g.AddComponent<SportsEventTruck>();t.body=b;t.shape=box;t.session=m;t.slot=slot;var visual=LWS.TruckHockey.Editor.HockeyAuthoring.TruckGeometry(g.transform,length);t.visuals=visual.transform;t.paint=visual.GetComponentsInChildren<Renderer>().First(r=>r.name=="Cab");t.engine=g.AddComponent<AudioSource>();t.engine.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/NWH/Vehicle Physics 2/Sound/Engine/Running/EngineRunning - Truck4.wav");t.engine.loop=true;t.engine.playOnAwake=false;var preset=AssetDatabase.LoadAssetAtPath<FrictionPreset>("Assets/NWH/WheelController/Resources/Wheel Controller 3D/Defaults/DefaultFrictionPreset.asset");t.wheels=new WheelController[4];for(int i=0;i<4;i++){var wgo=new GameObject("NWH event wheel "+i);wgo.layer=2;wgo.transform.SetParent(g.transform,false);wgo.transform.localPosition=new Vector3(i%2==0?-.5f:.5f,.04f,i<2?.9f:-.9f);var w=wgo.AddComponent<WheelController>();w.wheel.radius=.3f;w.wheel.width=.16f;w.wheel.mass=.7f;w.spring.maxLength=.12f;w.spring.maxForce=170;w.damper.bumpRate=w.damper.reboundRate=240;w.rollingResistanceTorque=.025f;w.FrictionPreset=preset;w.frictionSubsteps=10;w.forceApplicationPointDistance=.04f;w.layerMask=1;t.wheels[i]=w;}foreach(var c in g.GetComponentsInChildren<Collider>(true))c.gameObject.layer=2;t.Power(false);b.isKinematic=true;b.detectCollisions=false;return t;}
 public static SportsEventCamera Camera(string name){var root=new GameObject(name);var c=root.AddComponent<Camera>();c.tag="MainCamera";c.nearClipPlane=.08f;c.farClipPlane=900;c.fieldOfView=58;c.clearFlags=CameraClearFlags.Skybox;var adapter=root.AddComponent<SportsEventCamera>();adapter.view=c;adapter.target=new GameObject(name+" Stable target").transform;adapter.aim=new GameObject(name+" Stable aim").transform;var rig=new GameObject(name+" Cinemachine rig").AddComponent<CinemachineVirtualCamera>();adapter.rig=rig;rig.Follow=adapter.target;rig.LookAt=adapter.aim;rig.Priority=-100;adapter.follow=rig.AddCinemachineComponent<CinemachineTransposer>();adapter.follow.m_BindingMode=CinemachineTransposer.BindingMode.WorldSpace;adapter.follow.m_XDamping=adapter.follow.m_YDamping=adapter.follow.m_ZDamping=.4f;rig.AddCinemachineComponent<CinemachineComposer>();rig.enabled=false;return adapter;}
