  m.replayButtons=new GameObject[4];string[] replayKeys={"angle","speed","rewind","skip"};for(int i=0;i<4;i++)m.replayButtons[i]=SportsUIAuthoring.Button(m.hud.transform,replayKeys[i].ToUpper(),"replay"+replayKeys[i],new Vector2(-450+i*300,-365),new Vector2(270,48)).gameObject;
  p=SportsUIAuthoring.Page("Join",m.transform,"INPUT SOURCES","Reconnect or explicitly assign replacement · Release then freshly confirm");m.pages[2]=p;m.joinInfo=SportsUIAuthoring.Text("Assignments",p.transform,"",new Vector2(1300,390),new Vector2(0,70),26);for(int i=0;i<8;i++)SportsUIAuthoring.Button(p.transform,"REASSIGN "+(i+1),"reassign"+i,new Vector2(-495+i%4*330,-180-i/4*58),new Vector2(300,46));SportsUIAuthoring.Button(p.transform,"BACK TO SETUP","setup",new Vector2(-340,-370));SportsUIAuthoring.Button(p.transform,"START / RESUME","resume",new Vector2(340,-370));
